package configuration

import (
	"io/fs"
	"os"
	"strings"

	"github.com/hashicorp/hcl/v2"
	"github.com/hashicorp/hcl/v2/hclsyntax"
	hcljson "github.com/hashicorp/hcl/v2/json"

	log "github.com/cloudposse/atmos/pkg/logger"
	"github.com/cloudposse/atmos/pkg/perf"
)

var (
	terraformBlockSchema  = &hcl.BodySchema{Blocks: []hcl.BlockHeaderSchema{{Type: "terraform"}}}
	encryptionBlockSchema = &hcl.BodySchema{Blocks: []hcl.BlockHeaderSchema{{Type: "encryption"}}}
)

// UnencryptedRetainedFiles returns the retained generated files whose generated bytes configured
// OpenTofu state encryption (a `terraform { encryption { ... } }` block) while no Terraform file of
// the root module in directory configures it after the write. Those runs would keep state unencrypted,
// although the configuration asked for encryption.
//
// The check reads what is on disk after WriteFilesReport: the generated bytes only identify which
// file was meant to carry encryption. When a root module file cannot be read or parsed, the outcome is
// unknown and nothing is reported; OpenTofu itself rejects a module it cannot parse before it writes state.
func UnencryptedRetainedFiles(directory string, report WriteReport) []string {
	defer perf.Track(nil, "configuration.UnencryptedRetainedFiles")()

	var candidates []string
	for _, file := range report.Retained {
		if encrypted, known := declaresEncryption(file.Path, file.Content); known && encrypted {
			candidates = append(candidates, file.Path)
		}
	}
	if len(candidates) == 0 {
		return nil
	}
	encrypted, known := moduleDeclaresEncryption(directory)
	if !known || encrypted {
		return nil
	}
	return candidates
}

// moduleDeclaresEncryption reports whether any root module file configures state encryption, and
// whether every root module file could be inspected.
func moduleDeclaresEncryption(directory string) (bool, bool) {
	root, err := os.OpenRoot(directory)
	if err != nil {
		log.Debug("Cannot inspect the module for state encryption", "directory", directory, "error", err)
		return false, false
	}
	defer root.Close()
	entries, err := fs.ReadDir(root.FS(), ".")
	if err != nil {
		log.Debug("Cannot inspect the module for state encryption", "directory", directory, "error", err)
		return false, false
	}
	for _, entry := range entries {
		if !entry.Type().IsRegular() || terraformFileSyntax(entry.Name()) == syntaxNone {
			continue
		}
		content, err := root.ReadFile(entry.Name())
		if err != nil {
			log.Debug("Cannot inspect a module file for state encryption", "file", entry.Name(), "error", err)
			return false, false
		}
		encrypted, known := declaresEncryption(entry.Name(), content)
		if !known {
			return false, false
		}
		if encrypted {
			return true, true
		}
	}
	return false, true
}

type fileSyntax int

const (
	syntaxNone fileSyntax = iota
	syntaxNative
	syntaxJSON
)

// terraformFileSyntax returns how OpenTofu reads a root module file, or syntaxNone when it does not.
func terraformFileSyntax(name string) fileSyntax {
	switch {
	case strings.HasSuffix(name, ".tf.json"), strings.HasSuffix(name, ".tofu.json"):
		return syntaxJSON
	case strings.HasSuffix(name, ".tf"), strings.HasSuffix(name, ".tofu"):
		return syntaxNative
	}
	return syntaxNone
}

// declaresEncryption reports whether the file configures `terraform { encryption }`, and whether
// the file is a Terraform file that could be parsed.
func declaresEncryption(name string, content []byte) (bool, bool) {
	var file *hcl.File
	var diagnostics hcl.Diagnostics
	switch terraformFileSyntax(name) {
	case syntaxNative:
		file, diagnostics = hclsyntax.ParseConfig(content, name, hcl.InitialPos)
	case syntaxJSON:
		file, diagnostics = hcljson.Parse(content, name)
	default:
		return false, false
	}
	if diagnostics.HasErrors() {
		return false, false
	}
	blocks, _, diagnostics := file.Body.PartialContent(terraformBlockSchema)
	if diagnostics.HasErrors() {
		return false, false
	}
	for _, block := range blocks.Blocks {
		nested, _, diagnostics := block.Body.PartialContent(encryptionBlockSchema)
		if diagnostics.HasErrors() {
			return false, false
		}
		if len(nested.Blocks) > 0 {
			return true, true
		}
	}
	return false, true
}
